import { getRoleShortcutLimit } from "@/lib/roles";
import { PLANS, PREVIEW_HIGHLIGHT_NOTE } from "@/lib/plans";
import type { ClientEntitlements } from "@/lib/entitlements";
import { SEND_TIMING_DESCRIPTION } from "@/lib/email-limits";

export type TutorialHint =
  | "search"
  | "template"
  | "roles"
  | "shortlist"
  | "resume"
  | "queue"
  | "placeholders"
  | "editor"
  | "preview"
  | "saved"
  | "totals"
  | "statuses"
  | "uncertain"
  | "replies"
  | "history-shortlist"
  | "contacts"
  | "contact-form"
  | "import"
  | "import-review"
  | "preferences"
  | "gmail"
  | "pdf"
  | "limits"
  | "subscription"
  | "reminders"
  | "data";

export type TutorialStep = { title: string; text: string; hint: TutorialHint };

export const tutorials: Record<string, readonly TutorialStep[]> = {
  "/compose": [
    {
      title: "Search recipients",
      text: "Search Your shortlist by name, email, or company. Add new people in Contacts before choosing recipients here.",
      hint: "search",
    },
    {
      title: "Choose a template",
      text: "Choose the saved message you want to send. Use Manage Templates to create or edit it before selecting recipients.",
      hint: "template",
    },
    {
      title: "Apply a role",
      text: "Premium can select a recipient in Personal preview, then edit their role or choose a saved shortcut for this batch. Free uses the role saved in Contacts.",
      hint: "roles",
    },
    {
      title: "Build your shortlist",
      text: `Use Filter by Job Role and Select all to choose up to ${PLANS.PAID.campaignRecipients} eligible contacts. Unsent contacts appear automatically. Prepare follow-ups using Add to shortlist in History. Selecting a yellow recipient authorizes a follow-up; Select all skips previously emailed people, and pending deliveries stay disabled.`,
      hint: "shortlist",
    },
    {
      title: "Preview and attach",
      text: "Check each recipient’s Personal Preview before sending. Upload your PDF in Settings and select Attach PDF here—mentioning a PDF in the message does not attach it.",
      hint: "resume",
    },
    {
      title: "Read the Send Queue",
      text: `Check Selected recipients and View allowances, then use Send to recipients to approve this batch. Each person gets an individual email from your Gmail. The draft ring estimates sending time, including processing. ${SEND_TIMING_DESCRIPTION} Sent later means Gmail accepted an email, not confirmed delivery.`,
      hint: "queue",
    },
  ],
  "/templates": [
    {
      title: "Personalize with placeholders",
      text: "Use {{name}}, {{company}}, and {{role}} for each contact’s details. Insert buttons place a placeholder at the message cursor. Premium can override a recipient’s role in Compose.",
      hint: "placeholders",
    },
    {
      title: "Write your template",
      text: "Give the template a name, subject, and message. Use full HTTP/HTTPS URLs for clickable links; line breaks are preserved, with a plain-text alternative. Use **bold** for emphasis and start bullet lines with - or *.",
      hint: "editor",
    },
    {
      title: "Check the live preview",
      text: "The preview updates as you type; use Preview as to check another recipient. Fix unknown or unclosed placeholders before saving.",
      hint: "preview",
    },
    {
      title: "Save for Compose",
      text: "Save the template to make it available in Compose’s template dropdown. Saved templates appear below the editor with Edit and Delete controls.",
      hint: "saved",
    },
  ],
  "/history": [
    {
      title: "Read your totals",
      text: "Sent Today follows the UTC day. In queue counts pending emails, and Replies counts emails you marked manually. Queued emails reserve sending capacity.",
      hint: "totals",
    },
    {
      title: "Follow the queue",
      text: "An active queue shows progress and an approximate time remaining. Sent means Gmail accepted the email, not that it reached the recipient’s inbox. History refreshes while your queue is active.",
      hint: "queue",
    },
    {
      title: "Find a message",
      text: "Search by recipient or company and use the Queued, Sent, Failed, Replied, or Cancelled filter buttons. Rows retain the company, job role, and template used. Sent dates and times use your local time zone; Needs review is an uncertain attempt shown on a failed row.",
      hint: "statuses",
    },
    {
      title: "Mark replies and review errors",
      text: "Mailloop does not read your inbox or detect replies. Use Mark replied to stop reminders; Undo restores Sent status and makes due reminders eligible again. Failed rows explain errors. For Delivery needs review, check Gmail Sent yourself; uncertain attempts are never automatically resent.",
      hint: "replies",
    },
    {
      title: "Prepare a follow-up",
      text: "Use the circular + button on a Sent or Replied email to add its recipient to your shortlist. A check means In shortlist. Pending deliveries and unavailable contacts stay disabled. Review the recipient and message in Compose before sending.",
      hint: "history-shortlist",
    },
  ],
  "/contacts": [
    {
      title: "Find your contacts",
      text: "Search names, emails, or companies. The table shows each person’s company, job role, and last sent time.",
      hint: "contacts",
    },
    {
      title: "Add or edit a person",
      text: "Use the contact form to enter an email, name, company, and job role. Company is optional; review any name suggested from the email address. Enter any job role or choose a shortcut saved in Settings.",
      hint: "contact-form",
    },
    {
      title: "Preview an import",
      text: "Premium can upload a CSV or paste a list, then choose Preview Import. CSV files can be up to 1 MB and 1,000 rows. Use Bulk Job Role to assign roles; review missing names and invalid rows before confirming.",
      hint: "import",
    },
    {
      title: "Save your list",
      text: "Correct invalid rows, then choose Confirm import; duplicates are skipped. Any job role is allowed. Edit or delete existing contacts from their rows.",
      hint: "import-review",
    },
  ],
  "/usage": [
    {
      title: "Read your allowances",
      text: "Read remaining capacity alongside sent and queued counts. Queued emails reserve capacity. Reset times appear in UTC with your local equivalent; when plan limits are disabled, only a rolling 24-hour allowance applies.",
      hint: "limits",
    },
    {
      title: "Review your plan",
      text: "Usage shows your effective plan and sending allowances. Upgrade here when checkout is available. Settings shows verified renewal details and lets you manage or refresh a subscription. Access grants can differ from subscription status.",
      hint: "subscription",
    },
    {
      title: "Plan your next batch",
      text: `Choose up to ${PLANS.PAID.campaignRecipients} recipients within your remaining allowance and approve the batch in Compose. ${SEND_TIMING_DESCRIPTION} Each recipient receives an individual email from your Gmail. Ready sends expire after 24 hours and release unused reservations.`,
      hint: "queue",
    },
    {
      title: "Review uncertain attempts",
      text: "A claimed sending attempt uses capacity. An uncertain attempt keeps that capacity and is never automatically resent. Check Gmail Sent and review History before trying again; Gmail can apply additional limits.",
      hint: "uncertain",
    },
  ],
  "/settings": [
    {
      title: "Save role shortcuts",
      text: "Save role shortcuts with any role text, then choose Save Preferences to use them in Contacts. Premium can also use them for Compose overrides.",
      hint: "preferences",
    },
    {
      title: "Review your plan",
      text: "Plan and subscription shows verified renewal dates and subscription controls. Refresh subscription status after a billing change; open Usage for allowances. Access grants can differ from subscription status.",
      hint: "subscription",
    },
    {
      title: "Connect Gmail",
      text: "Check the Gmail connection status and use Reconnect Gmail when permissions need refreshing. Manage Access in Google opens your Google connection settings. If sending is paused, check the reason and any cooldown shown here.",
      hint: "gmail",
    },
    {
      title: "Manage your PDF attachment",
      text: "Upload one PDF up to 5 MB, then explicitly select Attach PDF in Compose. You can download, replace, or remove the saved PDF; queued emails keep their selected PDF.",
      hint: "pdf",
    },
    {
      title: "Set follow-up reminders",
      text: "Choose Off or 3, 7, or 14 days, then Save reminders. History shows due follow-ups when no reply is marked. Add the contact to your shortlist and approve each message in Compose; reminders never send automatically.",
      hint: "reminders",
    },
    {
      title: "Manage your data",
      text: "Download my data exports your profile, preferences, contacts, templates, history, and attachment metadata. Download your PDF separately. Delete history and Delete account in Danger zone require confirmation and cannot be undone.",
      hint: "data",
    },
  ],
};

export function tutorialRoleNote(access: ClientEntitlements): string {
  return `Any contact job role · up to ${getRoleShortcutLimit(access.effectivePlan)} saved shortcuts`;
}

export function tutorialPreviewNote(access: ClientEntitlements): string {
  return `${PREVIEW_HIGHLIGHT_NOTE} ${
    access.features.previewHighlightColors
      ? "Use the color picker beside Preview as or Preview recipient to choose your highlight color. Your browser remembers your choice."
      : "Use the crown beside Preview as or Preview recipient to learn about upgrading. Any saved Premium color is kept for when access returns."
  }`;
}

export function planTutorials(path: string, access: ClientEntitlements) {
  const text: Partial<Record<TutorialHint, string>> = {};
  if (path === "/templates") {
    if (access.paidGatingEnabled && access.limits.savedTemplates === null) {
      text.editor =
        "Choose New template or Edit to open the editor. Give your template a name, subject, and message. Paste full HTTP/HTTPS URLs to make them clickable. Emails wrap naturally and preserve your line breaks, with a plain-text alternative. Use **bold** for emphasis and start bullet lines with - or *.";
      text.preview =
        "Open a template row for a quick preview, or use its expand icon for a larger message view. Collapse or press Esc to return. In the editor, the personal preview updates as you type. Check placeholders before saving.";
      text.saved =
        "Search your library by name or subject. Each page shows up to 10 templates, with Edit, Download JSON, and Delete actions. Saved templates are available in Compose’s template dropdown.";
    } else if (access.limits.savedTemplates !== null) {
      text.editor =
        "Choose Create your first template or Edit template to update your active template. Give it a name, subject, and message with full URLs.";
      text.preview =
        "Your active template shows its subject and message. In the editor, use Preview as to check personalization and fix unknown or unclosed placeholders before saving.";
      text.saved = `Free includes ${access.limits.savedTemplates} active template for Compose. Use Edit template, Download JSON, or Delete on its card. Older templates stay saved but must be selected as the active one; Premium unlocks the full library.`;
    }
  }
  if (path === "/templates") {
    text.preview = `${text.preview ?? tutorials[path].find((step) => step.hint === "preview")?.text ?? "Check placeholders in the live preview."} ${tutorialPreviewNote(access)}`;
  }
  if (path === "/compose") {
    text.resume = `${tutorials[path].find((step) => step.hint === "resume")?.text ?? "Check your personal preview before sending."} ${tutorialPreviewNote(access)}`;
  }
  const repeatPreparation = access.features.historyShortlist
    ? "Use + in History to add someone to your shortlist and email them again."
    : "To email someone again, enter and save their details in Contacts to add them back to your shortlist. The + shortcut in History requires Premium.";
  if (!access.features.historyShortlist)
    text["history-shortlist"] =
      repeatPreparation +
      " Review the recipient and message in Compose before sending.";
  text.shortlist = `Use Filter by Job Role and Select all to choose up to ${access.limits.campaignRecipients} eligible contacts. Unsent contacts appear automatically. ${repeatPreparation} Selecting a yellow recipient authorizes a follow-up; Select all skips previously emailed people, and pending deliveries stay disabled. Manual repeat sends are included in both plans and count toward your allowances.`;
  if (!access.features.markReplied) {
    text.replies =
      "Mailloop does not read your inbox or detect replies. Mark replied and Undo require Premium. Failed rows explain errors; for Delivery needs review, check Gmail Sent yourself. Uncertain attempts are never automatically resent.";
  }
  if (!access.features.csvImport) {
    text.import =
      "CSV and pasted-list imports require Premium. You can still add contacts individually using the contact form. Existing contacts remain available.";
    text["import-review"] =
      "With Premium, preview a CSV or pasted list, correct invalid rows, and confirm the import; duplicates are skipped. Until then, use the contact form to save each person individually.";
  }
  if (!access.features.followUpReminders) {
    text.reminders =
      "Follow-up reminders require Premium. When available, choose Off or 3, 7, or 14 days and Save reminders. Reminders appear in History and never send emails automatically.";
  }
  text.roles = access.features.recipientRoleOverride
    ? "Select a recipient in Personal preview, then edit their role or choose a saved shortcut. The preview updates for that recipient and this batch only."
    : "Each recipient uses their saved job role. Edit it in Contacts; Premium can override roles for an individual batch in Compose.";
  if (path === "/settings") {
    text.preferences = `Save up to ${getRoleShortcutLimit(access.effectivePlan)} role shortcuts with any text, then click Save Preferences to use them in Contacts. Premium can also use them in Compose.`;
  }
  if (path === "/usage" || path === "/settings") {
    const subscription = tutorials[path].find(
      (step) => step.hint === "subscription",
    )!.text;
    const themes = access.features.blackThemes
      ? "Use Choose appearance for all four themes, including Chalk and Obsidian."
      : "Choose appearance includes Lavender and Nightbloom; Chalk and Obsidian require Premium.";
    const support = access.features.prioritySupport
      ? "Your plan includes prioritized email support."
      : "Ordinary support remains available; Premium includes prioritized email support.";
    text.subscription = `${subscription} ${themes} ${PREVIEW_HIGHLIGHT_NOTE} ${support}`;
  }
  text.limits = access.paidGatingEnabled
    ? `Your current allowance is ${access.limits.dailyEmails} daily and ${access.limits.monthlyEmails} monthly emails. Queued emails reserve both. Daily resets are at midnight UTC; Free monthly resets follow the UTC calendar month, while Premium follows the verified billing period. Reset times also show your local equivalent. Unused allowance does not roll over.`
    : `Your allowance is ${access.limits.dailyEmails} emails per rolling 24 hours, including sent and queued emails. Capacity returns as sends leave that window; there is no fixed midnight reset.`;

  return tutorials[path]?.map((step) => ({
    ...step,
    text:
      (text[step.hint] ?? step.text).replaceAll(
        `up to ${PLANS.PAID.campaignRecipients}`,
        `up to ${access.limits.campaignRecipients}`,
      ) +
      (["roles", "preferences", "contact-form", "import-review"].includes(
        step.hint,
      )
        ? ` ${tutorialRoleNote(access)}. Existing saved roles are retained.`
        : ""),
  }));
}
